/** 应用外壳与路由表。
 *
 * 路由与后端路径是**刻意对齐**的（都用 /plans、/reader/:id、/share/:token）：
 * 后端把所有未知 GET 都交给这个 SPA，所以刷新任何一个子路径都能正常落到对应页面。
 */

import { BrowserRouter, Link, Navigate, Route, Routes, useLocation } from 'react-router-dom'

import { AuthProvider, useAuth } from './auth'
import { AdminPage } from './pages/Admin'
import { LoginPage } from './pages/Login'
import { PlanPage } from './pages/Plan'
import { PlansPage } from './pages/Plans'
import { ReaderPage } from './pages/Reader'
import { RegisterPage } from './pages/Register'
import { ShareNotFound, SharePage } from './pages/Share'

function TopBar() {
  const { user, logout } = useAuth()
  const loc = useLocation()
  if (!user) return null
  return (
    <header className="topbar">
      <Link to="/plans" className="brand">papershelf</Link>
      <nav>
        <Link to="/plans" className={loc.pathname.startsWith('/plans') || loc.pathname.startsWith('/reader') ? 'active' : ''}>
          我的计划
        </Link>
        {user.is_admin && (
          <Link to="/admin" className={loc.pathname === '/admin' ? 'active' : ''}>用户管理</Link>
        )}
      </nav>
      <span className="who">{user.display_name || user.email}</span>
      <button className="ghost" style={{ fontSize: 13 }}
              onClick={() => void logout()}>退出</button>
    </header>
  )
}

/** 需要登录的页面 */
function Private({ children }: { children: React.ReactNode }) {
  const { user, loading } = useAuth()
  const loc = useLocation()
  if (loading) return <div className="page"><p className="muted">加载中…</p></div>
  if (!user) return <Navigate to={`/login?next=${encodeURIComponent(loc.pathname)}`} replace />
  return <>{children}</>
}

function Shell() {
  return (
    <div className="shell">
      <TopBar />
      <Routes>
        <Route path="/login" element={<LoginPage />} />
        <Route path="/register" element={<RegisterPage />} />
        {/* 分享是匿名可读的（⑪），不进 Private 包裹 */}
        <Route path="/share/:token" element={<SharePage />} />
        <Route path="/plans" element={<Private><PlansPage /></Private>} />
        <Route path="/plans/:planId" element={<Private><PlanPage /></Private>} />
        {/* 阅读器自带整屏布局，不套 .page 容器 */}
        <Route path="/reader/:paperId" element={<Private><ReaderPage /></Private>} />
        <Route path="/admin" element={<Private><AdminPage /></Private>} />
        <Route path="/" element={<Navigate to="/plans" replace />} />
        <Route path="*" element={<ShareNotFound />} />
      </Routes>
    </div>
  )
}

export function App() {
  return (
    <BrowserRouter>
      <AuthProvider>
        <Shell />
      </AuthProvider>
    </BrowserRouter>
  )
}

