.doc-h { font-family: var(--font-doc-serif); font-weight: 700; color: var(--fg); line-height: 1.28; margin: 18px 0 7px; break-after: avoid; }
.doc-h.lvl1 { font-size: calc(var(--doc-fs) + 3px); margin-top: 22px; }
