.doc-h .b-en, .doc-h .b-zh { display: block; }

.blk { break-inside: avoid; }
.blk-p { padding: 7px 9px; margin: 0 0 3px; border-radius: 6px; cursor: pointer; position: relative; transition: background .13s ease; }
.blk-p:hover { background: var(--fg-soft); }
.blk-p.is-sel { background: color-mix(in oklch, var(--accent) 8%, transparent); }
