.t-en { font-family: var(--font-doc-serif); font-size: var(--doc-fs); line-height: 1.62; text-align: justify; hyphens: auto; margin: 0; color: color-mix(in oklch, var(--fg) 84%, var(--muted)); }
.t-zh { font-family: var(--font-doc-han); font-size: calc(var(--doc-fs) + 0.5px); line-height: 1.82; text-align: justify; margin: 0; color: var(--fg); }
.b-zh { font-family: var(--font-doc-han); }
.lang-dual .pdf-page { width: min(1180px, 100%); }
.lang-dual .blk-p,
.lang-dual .doc-h,
.lang-dual .doc-title { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); column-gap: 36px; align-items: start; }
