/* ─── sidebar + shell ───────────────────────────────────────────── */
function renderShell() {
  const pl = activePlan(), list = papers();
  const bySt = countBy('st');
  const done = (bySt.read || 0) + (bySt.reviewed || 0);
  const pct = list.length ? Math.round(done / list.length * 100) : 0;
  const nm = $('#sidePlanName'); if (nm) nm.textContent = pl.name;
  const gt = $('#sideGoalTxt'); if (gt) gt.textContent = '已精读 ' + done + ' / 已入库 ' + list.length + ' 篇';
  const pp = $('#sidePlanPct'); if (pp) pp.textContent = pct + '%';
  const bar = $('#sidePlanBar'); if (bar) bar.style.width = pct + '%';
  const pg = $('#sidePlanGoal'); if (pg) pg.textContent = pl.goal + ' 篇';
  $('#navCountLib').textContent = list.length;
  const np = $('#navCountPlans'); if (np) np.textContent = state.plans.length;
  const v = viewMeta(state.view);
  $('#viewTitle').textContent = v.title;
  $('#viewSub').textContent = v.sub;
  $$('#nav .nav-item').forEach(b => b.classList.toggle('is-active', b.dataset.nav === state.view));
  const na = $('#navAdmin'); if (na) na.hidden = !isAdmin() || SHARE.active;
  const ncu = $('#navCountUsers'); if (ncu) ncu.textContent = Object.keys(readAccounts()).length;
  renderPlanMenu();
}

