{"content": "/* papershelf 设计系统 —— 端口自原型「文献台 PaperDesk」
 * （/Users/argszero/Downloads/t1/literature-workbench.html）
 *
 * 为什么整份照搬原型而不是"重新设计"：宿主已用原型确认过观感，M5 的目标是**对齐原型**，
 * 所以这里保留原型的 token 与类名（.tile / .ring / .pace-fig / .ptable / .doc-stage / .board …），
 * 只做两件事：① 收敛成一份可维护的样式表；② 为旧类名留别名，让未迁移的页面不至于崩。
 *
 * ⚠️ 浏览器要求（与原型一致）：oklch() 与 color-mix() 需要 Chrome 111+ / Safari 16.2+ / Firefox 113+。
 *    本项目另外要求 MathML Core（Chrome 109+），所以实际门槛由 color-mix 决定，二者都是 2023 年后的基线。
 *    降级行为：color-mix 不被支持时该条声明被丢弃（背景变透明/回到上级），**不会白屏**，功能仍可用。
 */

/* ── tokens ─────────────────────────────────────────────────────────── */
:root {
  --bg:      oklch(99% 0.002 240);
  --surface: oklch(100% 0 0);
  --fg:      oklch(18% 0.012 250);
  --muted:   oklch(54% 0.012 250);
  --border:  oklch(92% 0.005 250);
  --accent:  oklch(58% 0.18 255);

  --accent-soft: color-mix(in oklch, var(--accent) 14%, transparent);
  --fg-soft:     color-mix(in oklch, var(--fg) 6%, transparent);

  /* 状态色板：只用于数据编码，不做装饰 */
  --st-unread:  oklch(56% 0.012 250);
  --st-reading: oklch(58% 0.18 255);
  --st-read:    oklch(58% 0.14 150);
  --st-review:  oklch(52% 0.13 285);
  --warn:       oklch(70% 0.15 70);
  --danger:     oklch(58% 0.19 25);

  --font-display: -apple-system, BlinkMacSystemFont, 'SF Pro Display', system-ui, sans-serif;
  --font-body:    -apple-system, BlinkMacSystemFont, 'SF Pro Text', system-ui, sans-serif;
  --font-mono:    ui-monospace, 'JetBrains Mono', 'SF Mono', Menlo, monospace;
  /* 论文正文用衬线：文档是在**复现 PDF**，不是应用外壳 */
  --font-doc-serif: 'Iowan Old Style', 'Charter', Georgia, 'Times New Roman', serif;
  --font-doc-han:   'Songti SC', 'STSong', 'Source Han Serif SC', 'Noto Serif CJK SC', serif;

  --fs-body: 15px;
  --gap-xs: 8px; --gap-sm: 12px; --gap-md: 20px; --gap-lg: 32px; --gap-xl: 56px;
  --radius: 9px; --radius-lg: 14px;
  --topbar-h: 61px;
  --sidebar-w: 252px;

  /* 旧类名别名（未迁移页面仍可工作） */
  --ink: var(--fg);
  --ink-soft: var(--muted);
  --rule: var(--border);
  --bg-card: var(--surface);
  --chip: var(--fg-soft);
  --ok: var(--st-read);
}

*, *::before, *::after { box-sizing: border-box; }
html, body, #root { height: 100%; }
body {
  margin: 0; background: var(--bg); color: var(--fg);
  font-family: var(--font-body); font-size: var(--fs-body); line-height: 1.55;
  -webkit-font-smoothing: antialiased; text-rendering: optimizeLegibility;
}
img, svg { display: block; max-width: 100%; }
a { color: inherit; text-decoration: none; }
button { font: inherit; cursor: pointer; color: inherit; }
h1, h2, h3, h4 { margin: 0; }
p { margin: 0; text-wrap: pretty; }
:where(button, a, input, select, textarea, [tabindex]):focus-visible {
  outline: 2px solid var(--accent); outline-offset: 2px; border-radius: 6px;
}

.h2 { font-size: 26px; line-height: 1.12; letter-spacing: -0.02em; }
.h3 { font-size: 17px; font-weight: 600; letter-spacing: -0.01em; }
.eyebrow {
  font-family: var(--font-mono); font-size: 11px; letter-spacing: 0.09em;
  text-transform: uppercase; color: var(--muted); margin: 0;
}
.meta { font-family: var(--font-mono); font-size: 12px; color: var(--muted); }
.muted { color: var(--muted); font-size: 13.5px; }
.num { font-family: var(--font-mono); font-variant-numeric: tabular-nums; }

/* ── 按钮 / chips / pills / 标签 ────────────────────────────────────── */
.btn, button.btn {
  display: inline-flex; align-items: center; gap: 7px; padding: 9px 15px;
  border-radius: var(--radius); border: 1px solid transparent; font-size: 14px;
  font-weight: 540; letter-spacing: -0.005em; white-space: nowrap;
  background: transparent; transition: background .15s ease, border-color .15s ease;
}
.btn:active { transform: translateY(1px); }
.btn svg { width: 15px; height: 15px; }
.btn-primary, button.primary { background: var(--accent); color: var(--surface); border-color: var(--accent); }
.btn-primary:hover:not(:disabled), button.primary:hover:not(:disabled) { background: color-mix(in oklch, var(--accent) 86%, black); }
.btn-secondary { background: var(--surface); color: var(--fg); border-color: var(--border); }
.btn-secondary:hover:not(:disabled) { border-color: color-mix(in oklch, var(--fg) 32%, var(--border)); }
.btn-ghost, button.ghost { background: transparent; color: var(--muted); border-color: transparent; padding-inline: 9px; }
.btn-ghost:hover:not(:disabled), button.ghost:hover:not(:disabled) { color: var(--fg); background: var(--fg-soft); }
.btn-sm { padding: 6px 11px; font-size: 13px; }
button.danger, .btn-danger { color: var(--danger); border-color: color-mix(in oklch, var(--danger) 30%, var(--border)); background: var(--surface); }
button.danger:hover:not(:disabled) { background: color-mix(in oklch, var(--danger) 8%, var(--surface)); }
button:disabled, .btn:disabled { opacity: .5; cursor: not-allowed; }

.chip {
  display: inline-flex; align-items: center; gap: 6px; padding: 6px 12px;
  border: 1px solid var(--border); border-radius: 999px; background: var(--surface);
  color: var(--muted); font-size: 13px; transition: all .15s ease;
}
.chip:hover { color: var(--fg); border-color: color-mix(in oklch, var(--fg) 28%, var(--border)); }
.chip.is-on { background: var(--fg); color: var(--surface); border-color: var(--fg); }
.chip .c { font-family: var(--font-mono); font-size: 11px; opacity: .7; }
.chip.ok { color: var(--st-read); border-color: color-mix(in oklch, var(--st-read) 30%, var(--border)); }
.chip.warn { color: var(--warn); border-color: color-mix(in oklch, var(--warn) 34%, var(--border)); }
.chip.danger { color: var(--danger); border-color: color-mix(in oklch, var(--danger) 30%, var(--border)); }
.chip.accent { color: var(--accent); border-color: color-mix(in oklch, var(--accent) 30%, var(--border)); }

/* 状态药丸：颜色即数据（⑰ 四态） */
.pill { display: inline-flex; align-items: center; gap: 6px; padding: 3px 9px; border-radius: 999px; font-size: 12px; font-weight: 520; white-space: nowrap; }
.pill::before { content: ''; width: 6px; height: 6px; border-radius: 50%; background: currentColor; flex: none; }
.st-unread  { color: var(--st-unread);  background: color-mix(in oklch, var(--st-unread) 12%, transparent); }
.st-reading { color: var(--st-reading); background: color-mix(in oklch, var(--st-reading) 13%, transparent); }
.st-read    { color: var(--st-read);    background: color-mix(in oklch, var(--st-read) 13%, transparent); }
.st-review  { color: var(--st-review);  background: color-mix(in oklch, var(--st-review) 13%, transparent); }
.st-converting { color: var(--warn); background: color-mix(in oklch, var(--warn) 16%, transparent); }
.st-failed  { color: var(--danger); background: color-mix(in oklch, var(--danger) 13%, transparent); }

.tag { display: inline-flex; padding: 2px 8px; border: 1px solid var(--border); border-radius: 999px; font-size: 11px; color: var(--muted); white-space: nowrap; }

.mini { width: 60px; height: 5px; border-radius: 999px; background: var(--fg-soft); overflow: hidden; flex: none; }
.mini > i { display: block; height: 100%; border-radius: 999px; background: var(--fg); }
.mini.accent > i { background: var(--fg); }

.progress { height: 5px; background: var(--fg-soft); border-radius: 999px; overflow: hidden; min-width: 70px; }
.progress > i { display: block; height: 100%; background: var(--accent); }

/* ── 应用外壳 ───────────────────────────────────────────────────────── */
.app { display: grid; grid-template-columns: var(--sidebar-w) 1fr; height: 100vh; }

.sidebar {
  display: flex; flex-direction: column; gap: 6px; padding: 16px 12px;
  background: var(--surface); border-right: 1px solid var(--border); overflow-y: auto;
}
.brand { display: flex; align-items: center; gap: 10px; padding: 4px 8px 16px; }
.brand-mark {
  width: 34px; height: 34px; border-radius: 9px; background: var(--fg); color: var(--surface);
  display: grid; place-items: center; font-family: var(--font-display); font-weight: 600; font-size: 17px; flex: none;
}
.brand-name { font-weight: 600; font-size: 15.5px; letter-spacing: -0.01em; display: block; }
.brand-sub { font-family: var(--font-mono); font-size: 10px; letter-spacing: 0.1em; text-transform: uppercase; color: var(--muted); }
.sidenav { display: flex; flex-direction: column; gap: 2px; }
.nav-item {
  display: flex; align-items: center; gap: 11px; width: 100%; padding: 9px 11px;
  border: 0; background: transparent; border-radius: var(--radius); color: var(--muted);
  font-size: 14px; text-align: left; transition: background .15s ease, color .15s ease;
}
.nav-item svg { width: 17px; height: 17px; flex: none; }
.nav-item:hover { background: var(--fg-soft); color: var(--fg); }
.nav-item.is-active { background: var(--fg-soft); color: var(--fg); font-weight: 560; }
.nav-count { margin-left: auto; font-family: var(--font-mono); font-size: 11px; color: var(--muted); }
.side-sep { height: 1px; background: var(--border); margin: 12px 4px; }

.side-goal {
  margin-top: auto; width: 100%; text-align: left; font: inherit; cursor: pointer;
  border: 1px solid var(--border); border-radius: var(--radius-lg); padding: 14px;
  background: var(--surface); transition: border-color .15s ease, background .15s ease;
}
.side-goal:hover { background: var(--fg-soft); }
.side-goal .sg-top { display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 8px; }
.side-goal .sg-pct { font-family: var(--font-display); font-size: 22px; font-weight: 600; letter-spacing: -0.02em; }
.side-user { display: flex; align-items: center; gap: 10px; padding: 10px 6px 2px; }
.avatar {
  width: 32px; height: 32px; border-radius: 999px; background: var(--fg-soft); color: var(--fg);
  display: grid; place-items: center; font-size: 12.5px; font-weight: 600; flex: none;
}
.side-user .su-id { flex: 1; min-width: 0; }
.side-user .su-name { font-size: 13px; font-weight: 540; line-height: 1.2; display: block;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.side-user .su-sub { font-size: 11px; color: var(--muted); display: block;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

/* 计划切换器 */
.plan-wrap { position: relative; }
.plan-switch {
  display: flex; align-items: center; gap: 10px; width: 100%; padding: 9px 10px; margin-bottom: 6px;
  border: 1px solid var(--border); background: var(--surface); border-radius: var(--radius);
  color: var(--fg); text-align: left; transition: border-color .15s ease, background .15s ease;
}
.plan-switch:hover { background: var(--fg-soft); }
.plan-switch[aria-expanded="true"] { border-color: color-mix(in oklch, var(--fg) 34%, var(--border)); }
.ps-mark { width: 26px; height: 26px; border-radius: 7px; background: var(--fg-soft); color: var(--fg);
  display: grid; place-items: center; font-size: 12px; font-weight: 600; flex: none; }
.ps-txt { min-width: 0; display: flex; flex-direction: column; }
.ps-name { font-size: 13px; font-weight: 560; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ps-sub { font-size: 10.5px; color: var(--muted); }
.ps-chev { width: 15px; height: 15px; color: var(--muted); margin-left: auto; flex: none; transition: transform .15s ease; }
.plan-switch[aria-expanded="true"] .ps-chev { transform: rotate(180deg); }
.plan-pop {
  position: absolute; top: calc(100% - 2px); left: 0; right: 0; z-index: 20;
  background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-lg);
  box-shadow: 0 12px 32px rgba(0,0,0,.14); padding: 6px;
}
.pp-item { display: flex; align-items: center; gap: 10px; width: 100%; padding: 8px 9px; border: 0;
  background: transparent; border-radius: var(--radius); color: var(--fg); text-align: left; }
.pp-item:hover { background: var(--fg-soft); }
.pp-item.is-on { background: var(--fg-soft); }
.pp-mark { width: 24px; height: 24px; border-radius: 6px; background: var(--fg-soft); color: var(--fg);
  display: grid; place-items: center; font-size: 11.5px; font-weight: 600; flex: none; }
.pp-txt { min-width: 0; display: flex; flex-direction: column; flex: 1; }
.pp-n { font-size: 13px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.pp-s { font-family: var(--font-mono); font-size: 10.5px; color: var(--muted); }
.pp-tick { width: 15px; height: 15px; color: var(--fg); flex: none; }
.pp-sep { height: 1px; background: var(--border); margin: 5px 6px; }

/* ── 主区 + 顶栏 ────────────────────────────────────────────────────── */
.main { display: flex; flex-direction: column; height: 100vh; overflow: hidden; min-width: 0; }
.topbar {
  flex: none; display: flex; align-items: center; justify-content: space-between; gap: 20px;
  height: var(--topbar-h); padding: 0 24px; border-bottom: 1px solid var(--border);
  background: color-mix(in oklch, var(--bg) 88%, transparent); backdrop-filter: blur(12px); z-index: 8;
}
.tb-title { display: flex; align-items: baseline; gap: 12px; min-width: 0; }
.tb-title h1 { font-size: 19px; letter-spacing: -0.02em; white-space: nowrap; }
.tb-sub { font-family: var(--font-mono); font-size: 11.5px; color: var(--muted);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.tb-actions { display: flex; align-items: center; gap: 10px; flex: none; }
.search {
  display: flex; align-items: center; gap: 8px; padding: 7px 11px; border: 1px solid var(--border);
  border-radius: var(--radius); background: var(--surface); transition: border-color .15s ease;
}
.search:focus-within { border-color: color-mix(in oklch, var(--fg) 34%, var(--border)); }
.search svg { width: 15px; height: 15px; color: var(--muted); flex: none; }
.search input { border: 0; background: transparent; outline: none; font: inherit; font-size: 13.5px;
  color: var(--fg); width: 210px; padding: 0; }
.search input::placeholder { color: var(--muted); }

.view-scroll { flex: 1 1 auto; overflow-y: auto; }
.view { padding: 26px 24px 48px; max-width: 1420px; margin: 0 auto; width: 100%; }
.view-scroll.is-fill { overflow: hidden; display: flex; }
.view-scroll.is-fill .view { padding: 0; max-width: none; display: flex; flex-direction: column; min-height: 0; }

.sec-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 16px; margin-bottom: 16px; }
.grid { display: grid; gap: 16px; }
.g-4 { grid-template-columns: repeat(4, 1fr); }
.g-3 { grid-template-columns: repeat(3, 1fr); }
.g-2 { grid-template-columns: repeat(2, 1fr); }
.card { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-lg); padding: 20px; }
.card-h { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 16px; }
.card-h.wrap { flex-wrap: wrap; row-gap: 10px; }

.row { display: flex; gap: 10px; align-items: center; }
.row.wrap { flex-wrap: wrap; }
.spacer { flex: 1; }
.stack > * + * { margin-top: 10px; }

.tile { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-lg); padding: 18px; }
.tile .k { font-family: var(--font-mono); font-size: 11px; letter-spacing: 0.05em; text-transform: uppercase; color: var(--muted); }
.tile .v { font-family: var(--font-display); font-size: 30px; font-weight: 600; letter-spacing: -0.03em; line-height: 1.05; margin-top: 12px; }
.tile .v .u { font-size: 14px; color: var(--muted); font-weight: 500; margin-left: 3px; letter-spacing: 0; }
.tile .d { font-size: 12.5px; color: var(--muted); margin-top: 7px; }

/* 完成度圆环 + 图例 */
.ring-wrap { display: flex; align-items: center; gap: 26px; }
.ring { width: 138px; height: 138px; flex: none; }
.ring-center { position: relative; display: grid; place-items: center; }
.ring-center .rc-val { position: absolute; text-align: center; }
.rc-val b { font-family: var(--font-display); font-size: 32px; font-weight: 600; letter-spacing: -0.03em; display: block; }
.rc-val span { font-family: var(--font-mono); font-size: 10.5px; color: var(--muted); }
.legend { display: flex; flex-direction: column; gap: 12px; flex: 1; min-width: 0; }
.legend-row { display: flex; align-items: center; gap: 10px; font-size: 13.5px; }
.legend-row .sw { width: 9px; height: 9px; border-radius: 3px; flex: none; }
.legend-row .lv { margin-left: auto; font-family: var(--font-mono); font-size: 12.5px; color: var(--fg); }
.legend-row .lt { color: var(--muted); }
.stackbar { display: flex; height: 10px; border-radius: 999px; overflow: hidden; background: var(--fg-soft); }
.stackbar > i { display: block; height: 100%; }

/* 阅读节奏柱状图 */
.pace-fig { display: flex; align-items: flex-end; gap: 9px; height: 152px; }
.pace-fig.is-dense { gap: 3px; }
.pace-fig .bar { flex: 1; min-width: 0; display: flex; flex-direction: column; align-items: center;
  gap: 7px; height: 100%; justify-content: flex-end; }
.pace-fig .bar .fill { width: 100%; border-radius: 5px 5px 0 0;
  background: color-mix(in oklch, var(--fg) 78%, var(--surface)); transition: height .3s cubic-bezier(.4,0,.2,1); }
.pace-fig .bar.is-peak .fill { background: var(--fg); }
.pace-fig .bar .bl { font-family: var(--font-mono); font-size: 10px; color: var(--muted); white-space: nowrap; }
.pace-fig.is-dense .bar .num { display: none; }
.pace-fig.is-dense .bar .bl.is-off { visibility: hidden; }
.pace-stats { display: grid; grid-template-columns: repeat(4, 1fr); margin-top: 18px;
  border-top: 1px solid var(--border); padding-top: 14px; }
.pace-stat { padding: 0 12px; border-left: 1px solid var(--border); min-width: 0; }
.pace-stat:first-child { padding-left: 0; border-left: 0; }
.pace-stat .ps-k { font-family: var(--font-mono); font-size: 10px; letter-spacing: 0.05em;
  text-transform: uppercase; color: var(--muted); }
.pace-stat .ps-v { font-family: var(--font-display); font-size: 21px; font-weight: 600;
  letter-spacing: -0.02em; line-height: 1.1; margin-top: 5px; white-space: nowrap; }
.pace-stat .ps-v .u { font-size: 12px; color: var(--muted); font-weight: 500; margin-left: 2px; }
.pace-stat .ps-d { font-size: 11.5px; color: var(--muted); margin-top: 2px;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.pace-stat .ps-v.is-up { color: var(--st-read); }
.pace-stat .ps-v.is-down { color: var(--danger); }

/* 转换流水线 / 需要关注 / 最近阅读 */
.pipe-row { display: flex; align-items: center; gap: 12px; padding: 10px 0; border-top: 1px solid var(--border); }
.pipe-row:first-of-type { border-top: 0; }
.pipe-row .pr-dot { width: 8px; height: 8px; border-radius: 50%; flex: none; }
.pipe-row .pr-name { font-size: 13.5px; }
.pipe-row .pr-n { margin-left: auto; font-family: var(--font-mono); font-size: 13px; }

.attn-row { display: flex; align-items: center; gap: 12px; padding: 11px 0; border-top: 1px solid var(--border); }
.attn-row:first-child { border-top: 0; }
.attn-row .ar-ic { width: 30px; height: 30px; border-radius: 8px; display: grid; place-items: center;
  flex: none; background: var(--fg-soft); color: var(--muted); }
.attn-row .ar-ic svg { width: 15px; height: 15px; }
.attn-row.is-danger .ar-ic { color: var(--danger); background: color-mix(in oklch, var(--danger) 12%, transparent); }
.attn-row.is-warn .ar-ic { color: var(--warn); background: color-mix(in oklch, var(--warn) 15%, transparent); }
.attn-row .ar-t { font-size: 13.5px; }
.attn-row .ar-s { font-size: 12px; color: var(--muted); }

.recent-row { display: flex; align-items: center; gap: 12px; padding: 11px 0;
  border-top: 1px solid var(--border); cursor: pointer; width: 100%; background: none; border-inline: 0; border-bottom: 0;
  text-align: left; color: inherit; }
.recent-row:first-child { border-top: 0; }
.recent-row:hover .rr-t { color: var(--accent); }
.recent-row .rr-t { font-size: 13.5px; font-weight: 520; }
.recent-row .rr-s { font-size: 12px; color: var(--muted); }
.recent-row .rr-p { margin-left: auto; text-align: right; flex: none; }

/* ── 文献库 ─────────────────────────────────────────────────────────── */
.lib-toolbar { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; margin-bottom: 14px; }
.seg { display: inline-flex; background: var(--fg-soft); border-radius: var(--radius); padding: 3px; gap: 2px; }
.seg button { border: 1px solid transparent; background: transparent; padding: 6px 12px;
  border-radius: 7px; font-size: 13px; color: var(--muted); }
.seg button:hover { color: var(--fg); }
.seg button.is-on { background: var(--surface); color: var(--fg); border-color: var(--border); font-weight: 540; }

.input, .textarea, select.input {
  width: 100%; padding: 9px 12px; border: 1px solid var(--border); border-radius: var(--radius);
  background: var(--surface); color: var(--fg); font: inherit; font-size: 14px;
}
select.input { width: auto; }
.input:focus, .textarea:focus { outline: none; border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-soft); }
.textarea { min-height: 74px; resize: vertical; line-height: 1.55; }
.field { max-width: 420px; }
.field label, label { font-size: 13.5px; color: var(--muted); display: block; margin-bottom: 4px; }

.ptable { width: 100%; border-collapse: collapse; font-size: 13.5px; }
.ptable th { color: var(--muted); font-weight: 500; font-family: var(--font-mono); font-size: 11px;
  letter-spacing: 0.05em; text-transform: uppercase; text-align: left; padding: 10px 12px;
  border-bottom: 1px solid var(--border); }
.ptable td { padding: 13px 12px; border-bottom: 1px solid var(--border); vertical-align: middle; }
.ptable tbody tr { cursor: pointer; transition: background .12s ease; }
.ptable tbody tr:hover { background: var(--fg-soft); }
.ptable .t-title { font-weight: 545; font-size: 13.5px; line-height: 1.35; color: var(--fg); }
.ptable .t-sub { font-family: var(--font-mono); font-size: 11px; color: var(--muted); margin-top: 3px; }
.ptable .t-year { font-family: var(--font-mono); font-size: 12.5px; color: var(--fg); }
.ptable .t-venue { font-size: 12px; color: var(--muted); }
.ptable .t-tags { display: flex; gap: 4px; flex-wrap: wrap; max-width: 190px; }
.ptable .num-col { text-align: right; font-family: var(--font-mono); font-variant-numeric: tabular-nums; }
.table-foot { display: flex; align-items: center; justify-content: space-between; padding: 14px 2px 0; }
.empty { text-align: center; padding: 56px 20px; color: var(--muted); }

/* 旧表格类名（未迁移页面） */
table.list { width: 100%; border-collapse: collapse; font-size: 13.5px; }
table.list th { text-align: left; font-weight: 500; color: var(--muted); font-family: var(--font-mono);
  font-size: 11px; letter-spacing: 0.05em; text-transform: uppercase; padding: 10px 12px;
  border-bottom: 1px solid var(--border); }
table.list td { padding: 12px; border-bottom: 1px solid var(--border); vertical-align: top; }
table.list tr:hover td { background: var(--fg-soft); }

/* ── 阅读器 ─────────────────────────────────────────────────────────── */
.reader { display: flex; flex-direction: column; flex: 1; min-height: 0; }
.reader-toolbar {
  flex: none; display: flex; align-items: center; gap: 12px; padding: 11px 20px;
  border-bottom: 1px solid var(--border); background: var(--surface); overflow-x: auto;
}
.reader-toolbar .rt-title { min-width: 0; }
.reader-toolbar .rt-title .rt-t { font-weight: 570; font-size: 14px; white-space: nowrap;
  overflow: hidden; text-overflow: ellipsis; max-width: 340px; }
.reader-toolbar .rt-title .rt-s { font-family: var(--font-mono); font-size: 11px; color: var(--muted); }
.icon-btn {
  width: 34px; height: 34px; border: 1px solid var(--border); background: var(--surface);
  border-radius: var(--radius); display: grid; place-items: center; color: var(--muted); flex: none;
  transition: all .15s ease;
}
.icon-btn:hover:not(:disabled) { color: var(--fg); border-color: color-mix(in oklch, var(--fg) 30%, var(--border)); }
.icon-btn svg { width: 16px; height: 16px; }
.reader-body { flex: 1; min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr) 300px; }
.reader-body.no-rail { grid-template-columns: minmax(0, 1fr); }

/* 保版式的文档舞台（决策⑥：内容保真单栏；正文在"页"内，图表原位） */
.doc-stage {
  --doc-fs: 14.5px;
  flex: 1; min-height: 0; overflow-y: auto;
  background: color-mix(in oklch, var(--fg) 4.5%, var(--bg));
  padding: 26px 22px 72px;
}
.pdf-page {
  width: min(900px, 100%); margin: 0 auto 22px; background: var(--surface);
  border: 1px solid var(--border); border-radius: 3px; padding: 44px 50px 26px;
  box-shadow: 0 1px 1px color-mix(in oklch, var(--fg) 6%, transparent),
              0 20px 44px -30px color-mix(in oklch, var(--fg) 55%, transparent);
}
.page-body { display: block; }
.page-foot { display: flex; align-items: center; gap: 12px; margin-top: 28px; }
.page-foot .pf-rule { flex: 1; height: 1px; background: var(--border); }
.page-foot .pf-no { font-family: var(--font-mono); font-size: 10.5px; color: var(--muted); white-space: nowrap; }

.doc-head { margin-bottom: 20px; padding-bottom: 16px; border-bottom: 1px solid var(--border); }
.doc-venue { font-family: var(--font-mono); font-size: 11px; color: var(--muted); letter-spacing: 0.03em; margin: 0 0 10px; }
.doc-title { font-family: var(--font-doc-serif); font-size: 27px; line-height: 1.18; letter-spacing: -0.01em; margin: 0 0 12px; }
.doc-title .b-en, .doc-title .b-zh { display: block; }
.doc-title .b-zh { font-size: 24px; font-weight: 600; margin-top: 6px; }
.doc-authors { font-family: var(--font-doc-serif); font-size: 14px; line-height: 1.5; margin: 0 0 3px; }
.doc-affil { font-size: 12.5px; color: var(--muted); margin: 0; }

.doc-h { font-family: var(--font-doc-serif); font-weight: 700; color: var(--fg); line-height: 1.28;
  margin: 18px 0 7px; break-after: avoid; }
.doc-h.lvl1 { font-size: calc(var(--doc-fs) + 3px); margin-top: 22px; }
.doc-h.lvl2 { font-size: calc(var(--doc-fs) + 1.5px); margin-top: 16px; }
.doc-h.lvl3 { font-size: calc(var(--doc-fs) + 0.5px); font-style: italic; margin-top: 14px; }
.doc-h .b-en, .doc-h .b-zh { display: block; }

.blk { break-inside: avoid; }
.blk-p { padding: 7px 9px; margin: 0 0 3px; border-radius: 6px; cursor: pointer; position: relative;
  transition: background .13s ease; }
.blk-p:hover { background: var(--fg-soft); }
.blk-p.is-sel { background: color-mix(in oklch, var(--accent) 8%, transparent); }
.blk-p.is-sel::before { content: ''; position: absolute; left: 0; top: 10px; bottom: 10px; width: 3px;
  border-radius: 3px; background: var(--accent); }
.t-en { font-family: var(--font-doc-serif); font-size: var(--doc-fs); line-height: 1.62;
  text-align: justify; hyphens: auto; margin: 0; color: color-mix(in oklch, var(--fg) 84%, var(--muted)); }
.t-zh { font-family: var(--font-doc-han); font-size: calc(var(--doc-fs) + 0.5px); line-height: 1.82;
  text-align: justify; margin: 0; color: var(--fg); }
.b-zh { font-family: var(--font-doc-han); }

.lang-dual .pdf-page { width: min(1180px, 100%); }
.lang-dual .blk-p, .lang-dual .doc-h, .lang-dual .doc-title {
  display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); column-gap: 36px; align-items: start;
}
.lang-dual .cap { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  column-gap: 36px; align-items: baseline; }
.lang-dual .cap .cap-no { grid-column: 1 / -1; }
.lang-dual .doc-title .b-zh { margin-top: 0; }
.lang-dual .blk-p { padding: 8px 10px; margin-bottom: 7px; }
.lang-dual .blk-p .t-en { color: color-mix(in oklch, var(--fg) 76%, var(--muted)); }
.lang-zh .t-en, .lang-zh .b-en { display: none !important; }
.lang-en .t-zh, .lang-en .b-zh { display: none !important; }

.fig { margin: 15px 0; }
.fig.span-full, .tbl.span-full { margin: 20px 0; }
.cap { font-size: calc(var(--doc-fs) - 1.5px); line-height: 1.62;
  color: color-mix(in oklch, var(--fg) 80%, var(--muted)); margin: 8px 0 0; }
.cap .cap-no { font-family: var(--font-mono); font-size: 10.5px; letter-spacing: 0.05em;
  text-transform: uppercase; color: var(--muted); margin-right: 7px; }
.cap .b-en, .cap .b-zh { display: block; }
.cap .b-zh { margin-top: 2px; }
.tbl { margin: 16px 0; }
.tbl .cap { margin: 0 0 10px; }
.tbl-wrap { overflow-x: auto; }
.booktbl { width: 100%; border-collapse: collapse; font-size: calc(var(--doc-fs) - 1.5px); }
.booktbl th { border-top: 1.3px solid var(--fg); border-bottom: 0.7px solid var(--fg); padding: 7px 9px;
  text-align: left; vertical-align: bottom; font-family: var(--font-body); font-weight: 600; }
.booktbl td { padding: 6px 9px; vertical-align: top; font-family: var(--font-mono); font-variant-numeric: tabular-nums; }
.booktbl th:first-child, .booktbl td:first-child { padding-left: 2px; }
.booktbl th:last-child, .booktbl td:last-child { padding-right: 2px; }

/* 公式：服务端已渲染为 MathML（遗留项 8，零 JS 零字体） */
.math-display { display: block; text-align: center; margin: 14px 0; overflow-x: auto; overflow-y: hidden; }
.math-inline { display: inline-block; vertical-align: middle; }
math { font-size: 1.02em; max-width: 100%; }
.math-raw { font-size: .92em; background: var(--fg-soft); padding: 1px 4px; border-radius: 3px; }
.eq { position: relative; margin: 13px 0; padding: 11px 34px 11px 14px; text-align: center;
  font-family: var(--font-doc-serif); font-size: calc(var(--doc-fs) + 0.5px); line-height: 1.9; }
.eq .eq-no { position: absolute; right: 2px; top: 50%; transform: translateY(-50%);
  font-family: var(--font-mono); font-size: 11px; color: var(--muted); }

/* 右侧 rail：笔记 / 大纲 */
.reader-rail { background: var(--surface); display: flex; flex-direction: column; min-height: 0;
  border-left: 1px solid var(--border); }
.rail-tabs { flex: none; display: flex; border-bottom: 1px solid var(--border); }
.rail-tabs button { flex: 1; border: 0; background: transparent; padding: 11px 8px; font-size: 12.5px;
  color: var(--muted); border-bottom: 2px solid transparent; margin-bottom: -1px; }
.rail-tabs button.is-on { color: var(--fg); border-bottom-color: var(--fg); font-weight: 540; }
.rail-body { flex: 1; min-height: 0; overflow-y: auto; padding: 16px; }
.outline-item { display: flex; gap: 10px; padding: 8px; border-radius: 7px; font-size: 13px;
  color: var(--muted); cursor: pointer; width: 100%; border: 0; background: none; text-align: left; }
.outline-item:hover { background: var(--fg-soft); color: var(--fg); }
.outline-item.is-on { color: var(--fg); font-weight: 540; }
.outline-item .oi-n { font-family: var(--font-mono); font-size: 11px; color: var(--muted); }
.note-card { border: 1px solid var(--border); border-radius: var(--radius); padding: 12px;
  margin-bottom: 10px; background: var(--bg); }
.note-card .nc-head { display: flex; align-items: center; gap: 8px; margin-bottom: 6px; }
.note-card .nc-q { font-family: var(--font-mono); font-size: 10.5px; color: var(--muted); }
.note-card .nc-t { font-size: 13px; line-height: 1.55; white-space: pre-wrap; }
.note-card .nc-del { margin-left: auto; color: var(--muted); background: none; border: 0;
  font-size: 16px; line-height: 1; padding: 2px 4px; border-radius: 5px; }
.note-card .nc-del:hover { color: var(--danger); background: var(--fg-soft); }
.note-form { border-top: 1px solid var(--border); padding: 14px 16px; flex: none; background: var(--surface); }
.note-form .nf-target { font-family: var(--font-mono); font-size: 10.5px; color: var(--muted); margin-bottom: 8px; }
.note { border: 1px solid var(--border); border-radius: var(--radius); padding: 10px;
  font-size: 13px; background: var(--bg); }
.notelist { display: flex; flex-direction: column; gap: 8px; }

.block-tools { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 4px; opacity: 0; transition: opacity .12s; }
.blk-p:hover .block-tools, .blk-p:focus-within .block-tools { opacity: 1; }
.block-tools button { font-size: 12px; padding: 2px 8px; border: 1px solid var(--border);
  border-radius: 6px; background: var(--surface); color: var(--muted); }
.block-tools button:hover { color: var(--accent); border-color: var(--accent); }

/* ── 进度看板 ───────────────────────────────────────────────────────── */
.board { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; align-items: start; }
.board .col { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-lg);
  padding: 12px; transition: border-color .15s ease, background .15s ease; min-height: 120px; }
.board .col.is-over { border-color: var(--accent); background: color-mix(in oklch, var(--accent) 5%, var(--surface)); }
.col-head { display: flex; align-items: center; gap: 8px; padding: 4px 4px 12px; }
.col-head .ch-dot { width: 8px; height: 8px; border-radius: 50%; }
.col-head .ch-n { font-size: 13px; font-weight: 560; }
.col-head .ch-c { margin-left: auto; font-family: var(--font-mono); font-size: 11.5px; color: var(--muted); }
.kcard { background: var(--bg); border: 1px solid var(--border); border-radius: var(--radius);
  padding: 12px; margin-bottom: 9px; cursor: grab; transition: border-color .15s ease, transform .12s ease; }
.kcard:hover { border-color: color-mix(in oklch, var(--fg) 26%, var(--border)); }
.kcard:active { cursor: grabbing; }
