.kcard .kc-m { font-family: var(--font-mono); font-size: 10.5px; color: var(--muted); margin-bottom: 9px; }
.kcard .kc-foot { display: flex; align-items: center; gap: 6px; }

/* ── 抽屉 / 遮罩 / 提示 ─────────────────────────────────────────────── */
.drawer-mask { position: fixed; inset: 0; background: rgba(20,20,20,.28); z-index: 50; }
.drawer {
  position: fixed; top: 0; right: 0; height: 100%; width: min(560px, 94vw); background: var(--surface);
  border-left: 1px solid var(--border); z-index: 51; display: flex; flex-direction: column;
  box-shadow: -18px 0 44px -28px rgba(0,0,0,.4);
}
.drawer header { display: flex; align-items: center; gap: 10px; padding: 14px 18px; border-bottom: 1px solid var(--border); }
.drawer .body { padding: 18px; overflow-y: auto; flex: 1; }

.drop { border: 2px dashed var(--border); border-radius: var(--radius); padding: 26px; text-align: center;
  color: var(--muted); background: var(--bg); }
.drop.over { border-color: var(--accent); background: var(--accent-soft); color: var(--accent); }

.banner { padding: 10px 14px; border-radius: var(--radius); font-size: 14px; margin-bottom: 14px; }
.banner.error { background: color-mix(in oklch, var(--danger) 8%, var(--surface));
