  border: 1px solid color-mix(in oklch, var(--st-read) 30%, var(--border)); color: var(--st-read); }
.banner.warn { background: color-mix(in oklch, var(--warn) 10%, var(--surface));
  border: 1px solid color-mix(in oklch, var(--warn) 34%, var(--border)); color: color-mix(in oklch, var(--warn) 70%, var(--fg)); }

.toast {
  position: fixed; left: 50%; bottom: 28px; transform: translateX(-50%); z-index: 80;
  background: var(--fg); color: var(--surface); padding: 10px 18px; border-radius: 999px;
  font-size: 13.5px; box-shadow: 0 12px 30px rgba(0,0,0,.22);
}

.tabs { display: flex; gap: 4px; border-bottom: 1px solid var(--border); margin-bottom: 14px; }
.tabs button { border: 0; border-bottom: 2px solid transparent; border-radius: 0; background: transparent;
  color: var(--muted); padding: 8px 12px; }
.tabs button.active { color: var(--accent); border-bottom-color: var(--accent); }

/* ── 认证页 ─────────────────────────────────────────────────────────── */
.auth-wrap { min-height: 100vh; display: grid; place-items: center; padding: 32px 20px; }
.auth-card { width: min(430px, 100%); background: var(--surface); border: 1px solid var(--border);
  border-radius: var(--radius-lg); padding: 32px; }
.auth-logo { display: flex; justify-content: center; margin-bottom: 16px; }

/* ── 响应式 ─────────────────────────────────────────────────────────── */
@media (max-width: 1180px) {
  .g-4 { grid-template-columns: repeat(2, 1fr); }
  .board { grid-template-columns: repeat(2, 1fr); }
  .reader-body { grid-template-columns: minmax(0, 1fr); }
  .reader-rail { display: none; }
}
@media (max-width: 900px) {
  .app { grid-template-columns: 1fr; }
  .sidebar { display: none; }
  .g-4, .g-3, .g-2 { grid-template-columns: 1fr; }
  .lang-dual .blk-p, .lang-dual .doc-h, .lang-dual .doc-title, .lang-dual .cap { display: block; }
