/** 只读分享视图（决策⑩⑪）—— 匿名可访问，**没有任何写入口**。
 *  数据来自 `/api/shares/{token}*` 白名单（后端中间件对非 GET 一律 403）。 */

import { useCallback, useEffect, useState } from 'react'
import { Link, useParams } from 'react-router-dom'

import { ApiError, api } from '../api'
import type { PaperDoc } from '../types'

type SharedPlan = Awaited<ReturnType<typeof api.sharedPlan>>

export function SharePage() {
  const { token = '' } = useParams()
  const [plan, setPlan] = useState<SharedPlan | null>(null)
  const [doc, setDoc] = useState<PaperDoc | null>(null)
  const [paperId, setPaperId] = useState<number | null>(null)
  const [error, setError] = useState('')

  const loadDoc = useCallback(async (pid: number) => {
    setPaperId(pid)
    setError('')
    try { setDoc(await api.sharedDoc(token, pid)) }
    catch (e) {
      setDoc(null)
      setError(e instanceof ApiError ? e.message : '这篇文献暂时无法阅读')
    }
  }, [token])

  useEffect(() => {
    api.sharedPlan(token).then((p) => {
      setPlan(p)
      const first = p.papers.find((x) => x.conv_state === 'done')
      if (first) void loadDoc(first.id)
    }).catch((e) => setError(e instanceof ApiError ? e.message : '分享链接无效'))
  }, [token, loadDoc])

  if (error && !plan) {
    return <div className="page"><div className="banner error">{error}</div></div>
  }
  if (!plan) return <div className="page"><p className="muted">加载中…</p></div>

  return (
    <div className="reader">
      <div className="reader-bar">
        <span className="chip accent">只读分享</span>
        <strong style={{ flex: 1, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
          {plan.plan.name}
        </strong>
        <span className="muted">{plan.papers.length} 篇</span>
      </div>
      <div className="reader-body">
        <div className="reader-cols">
          <div className="card" style={{ marginBottom: 18 }}>
            <div className="stack">
              {plan.papers.map((p) => (
                <div className="row" key={p.id} style={{ gap: 8 }}>
                  <button className="ghost" onClick={() => void loadDoc(p.id)}
                          disabled={p.conv_state !== 'done'}>
                    {p.title || `文献 #${p.id}`}
                  </button>
                  {p.id === paperId && <span className="chip accent">当前</span>}
                  <div className="spacer" />
                  {p.conv_state === 'failed'
                    ? <span className="chip danger">转换失败</span>
                    : p.conv_state !== 'done' && <span className="chip warn">转换中</span>}
                  <a className="btn" href={api.sharedExportUrl(token, p.id, 'dual')}
                     target="_blank" rel="noreferrer">导出</a>
                </div>
              ))}
            </div>
          </div>
          {doc?.blocks.map((b) => {
            const wide = b.no_zh || !(b.zh || '').trim()
            return (
              <div className={`pair${wide ? ' wide' : ''}`} key={b.id}>
                <div className="col en"
                     dangerouslySetInnerHTML={{ __html: b.en_html || b.en }} />
                <div className="col zh"
                     dangerouslySetInnerHTML={{ __html: b.zh_html || b.zh || b.en }} />
              </div>
            )
          })}
          {error && plan && <div className="banner error">{error}</div>}
          {!doc && !error && <p className="muted">选择一篇开始阅读。</p>}
        </div>
      </div>
    </div>
  )
}

