  const done = papers.filter((p) => isDone(p.status)).length
  const n = papers.length
  const pct = n ? Math.round((done / n) * 100) : 0

  return <OverviewBody {...{ plan, papers, loading, range, setRange, byStatus, byConv, done, n, pct }} />
