  /* ─── reading plans ─────────────────────────────────────────────── */
  .plan-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }
  .plan-card { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-lg); padding: 20px; display: flex; flex-direction: column; transition: border-color .15s ease; }
  .plan-card:hover { border-color: color-mix(in oklch, var(--fg) 26%, var(--border)); }
