  .plan-card .pc-t { font-size: 16px; font-weight: 580; letter-spacing: -0.01em; }
  .plan-card .pc-d { font-size: 12.5px; color: var(--muted); line-height: 1.6; margin-top: 5px; min-height: 40px; }
  .plan-card .pc-stats { display: flex; flex-wrap: wrap; gap: 4px 14px; }
  .plan-card .pc-foot { display: flex; align-items: center; gap: 8px; margin-top: 16px; }
  .plan-new { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 8px; min-height: 200px; border: 1.5px dashed var(--border); border-radius: var(--radius-lg); background: transparent; color: var(--muted); transition: border-color .15s ease, color .15s ease; }
  .plan-new:hover { border-color: color-mix(in oklch, var(--fg) 30%, var(--border)); color: var(--fg); }
  .plan-new svg { width: 22px; height: 22px; }
  .plan-new > span:first-of-type { font-size: 14px; font-weight: 540; }

  /* ─── modal ─────────────────────────────────────────────────────── */
  .modal { position: fixed; inset: 0; z-index: 70; display: none; align-items: center; justify-content: center; padding: 24px; }
  .modal.is-open { display: flex; }
  .modal-scrim { position: absolute; inset: 0; background: color-mix(in oklch, var(--fg) 38%, transparent); }
  .modal-card { position: relative; width: min(440px, 100%); background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-lg); box-shadow: 0 20px 50px rgba(0,0,0,.22); display: flex; flex-direction: column; }
  .mc-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; padding: 18px 20px; border-bottom: 1px solid var(--border); }
  .mc-body { padding: 20px; display: flex; flex-direction: column; gap: 14px; }
