function renderOverview() {
  const pl = activePlan(), list = papers();
  const bySt = countBy('st'), byCv = countBy('cv');
  const done = (bySt.read || 0) + (bySt.reviewed || 0);
  const n = list.length;
  const pct = n ? Math.round(done / n * 100) : 0;
  const r = 60, c = 2 * Math.PI * r, off = c * (1 - pct / 100);
  const remain = Math.max(0, pl.goal - n);
  const weekDone = ((pl.pace.d7 && pl.pace.d7.bars) || []).reduce((a, b) => a + b.v, 0);
  const weekPlan = 7.6;
  const recent = list.slice().sort((a, b) => b.upd.localeCompare(a.upd)).slice(0, 5);
  const pctOf = x => n ? Math.round((x || 0) / n * 100) : 0;

  const segs = n ? ['unread', 'reading', 'read', 'reviewed'].map(k =>
    '<i style="width:' + ((bySt[k] || 0) / n * 100) + '%;background:' + STATUS[k].color + '"></i>').join('') : '';

  $('#view').innerHTML =
    '<section data-od-id="overview-stats" class="grid g-4" style="margin-bottom:16px">' +
      tile('阅读目标', pl.goal, '篇', '已入库 ' + n + ' 篇 · 完成 ' + pctOf(n) + '%') +
      tile('已精读', done, '篇', '占已入库 ' + pct + '%') +
      tile('中文版已生成', byCv.done || 0, '篇', '转换中 ' + (byCv.doing || 0) + ' · 待转换 ' + (byCv.none || 0)) +
      tile('本周精读', weekDone, '篇', '本周新增入库 ' + pl.weeklyAdded + ' 篇') +
    '</section>' +

    '<section class="grid g-2" style="grid-template-columns:1.35fr 1fr;margin-bottom:16px" data-od-id="overview-progress">' +
      '<div class="card">' +
        '<div class="card-h"><div><span class="eyebrow">阅读进度</span><h3 class="h3" style="margin-top:5px">库内精读完成度</h3></div>' +
        '<span class="meta">目标 ' + pl.goal + ' 篇</span></div>' +
        '<div class="ring-wrap">' +
          '<div class="ring-center">' +
            '<svg class="ring" viewBox="0 0 138 138" role="img" aria-label="库内精读完成度 ' + pct + '%">' +
              '<circle cx="69" cy="69" r="' + r + '" fill="none" stroke-width="9" style="stroke:var(--fg-soft)"/>' +
              '<circle cx="69" cy="69" r="' + r + '" fill="none" stroke-width="9" stroke-linecap="round" style="stroke:var(--accent)" stroke-dasharray="' + c.toFixed(1) + '" stroke-dashoffset="' + off.toFixed(1) + '" transform="rotate(-90 69 69)"/>' +
            '</svg>' +
            '<span class="rc-val"><b>' + pct + '%</b><span>已精读</span></span>' +
          '</div>' +
          '<div class="legend">' +
            legend('待读', STATUS.unread.color, bySt.unread || 0) +
            legend('在读', STATUS.reading.color, bySt.reading || 0) +
            legend('已读', STATUS.read.color, bySt.read || 0) +
            legend('已整理', STATUS.reviewed.color, bySt.reviewed || 0) +
          '</div>' +
        '</div>' +
        '<div class="stackbar" style="margin-top:20px" role="img" aria-label="状态分布">' + segs + '</div>' +
      '</div>' +
      '<div class="card">' +
        '<div class="card-h"><div><span class="eyebrow">转换流水线</span><h3 class="h3" style="margin-top:5px">中文版生成</h3></div>' +
        '<button class="btn btn-ghost btn-sm" id="openQueue">打开队列</button></div>' +
