 *  数据来自 `/api/shares/{token}*` 白名单（后端中间件对非 GET 一律 403）。
 *
 * 观感对齐原型：**与阅读器同一套文档舞台**（原型 `.doc-stage` 复用），
 * 差别只在顶部：没有工具栏、没有右栏、没有块工具 —— 只剩「只读分享」标识。
 * 所以这里直接复用 `DocBlock`，而不是另写一套 `pair/.col` 双栏
 * （那套类名在 M5 迁移后已随旧页面删除，会渲染成无样式的一列）。
 */

import { useCallback, useEffect, useState } from 'react'
import { Link, useParams } from 'react-router-dom'

import { ApiError, api } from '../api'
import { DocBlock } from './Reader'
import type { PaperDoc } from '../types'

type SharedPlan = Awaited<ReturnType<typeof api.sharedPlan>>

export function SharePage() {
  const { token = '' } = useParams()
  const [plan, setPlan] = useState<SharedPlan | null>(null)
  const [doc, setDoc] = useState<PaperDoc | null>(null)
  const [paperId, setPaperId] = useState<number | null>(null)
  const [error, setError] = useState('')

  const loadDoc = useCallback(async (pid: number) => {
    setPaperId(pid)
    setError('')
    try { setDoc(await api.sharedDoc(token, pid)) }
    catch (e) {
      setDoc(null)
      setError(e instanceof ApiError ? e.message : '这篇文献暂时无法阅读')
    }
  }, [token])

  useEffect(() => {
    api.sharedPlan(token).then((p) => {
      setPlan(p)
      const first = p.papers.find((x) => x.conv_state === 'done')
      if (first) void loadDoc(first.id)
    }).catch((e) => setError(e instanceof ApiError ? e.message : '分享链接无效'))
  }, [token, loadDoc])

  if (error && !plan) {
    return (
      <div className="auth-wrap">
        <div className="card" style={{ maxWidth: 440, width: '100%' }}>
          <h1 className="h2" style={{ fontSize: 20 }}>链接不可用</h1>
          <p className="meta" style={{ marginTop: 8, lineHeight: 1.7 }}>
            {error}。分享链接可能已被撤销或已过期。
          </p>
          <Link className="btn btn-secondary" style={{ marginTop: 14 }} to="/login">前往登录</Link>
        </div>
      </div>
    )
  }
  if (!plan) return <div className="auth-wrap"><p className="muted">加载中…</p></div>

  const current = plan.papers.find((p) => p.id === paperId) || null
  const shown = doc ? doc.blocks : []

  return (
    <section className="reader">
      <div className="reader-toolbar">
        <span className="pill st-reading">只读分享</span>
        <div className="rt-title" style={{ flex: 1 }}>
          <div className="rt-t">{plan.plan.name}</div>
          <div className="rt-s">
            {current ? (current.title || `文献 #${current.id}`) : `${plan.papers.length} 篇`}
            {' · 实时只读，读到的永远是当前版本'}
          </div>
        </div>
        {current && (
          <a className="btn btn-secondary btn-sm" href={api.sharedExportUrl(token, current.id, 'dual')}
             target="_blank" rel="noreferrer">导出</a>
        )}
      </div>

      <div className="reader-body" style={{ gridTemplateColumns: 'minmax(0, 1fr)' }}>
        <div className="doc-stage lang-dual">
          <div className="pdf-page">
            <div className="page-body">
              <nav className="share-picker">
                {plan.papers.map((p) => (
                  <button key={p.id} className={`chip${p.id === paperId ? ' is-on' : ''}`}
                          disabled={p.conv_state !== 'done'}
                          onClick={() => void loadDoc(p.id)}>
                    {p.title || `文献 #${p.id}`}
                    {p.conv_state === 'failed' ? ' · 转换失败'
                      : p.conv_state !== 'done' ? ' · 转换中' : ''}
                  </button>
                ))}
              </nav>

              {error && <div className="banner error">{error}</div>}
              {!doc && !error && <p className="muted">选择一篇开始阅读。</p>}

              {doc && (
                <header className="doc-head">
                  <p className="doc-venue">
                    {[doc.meta.journal, current?.venue, current?.year].filter(Boolean).join(' · ')
                      || (current?.source === 'arxiv' ? `arXiv ${current.source_ref || ''}` : 'PDF')}
                  </p>
                  <h1 className="doc-title">
                    {doc.meta.title_en && <span className="b-en">{String(doc.meta.title_en)}</span>}
                    {doc.meta.title_zh && <span className="b-zh">{String(doc.meta.title_zh)}</span>}
                  </h1>
                  {doc.meta.authors && <p className="doc-authors">{String(doc.meta.authors)}</p>}
                  {Array.isArray(doc.meta.affiliations) && (doc.meta.affiliations as string[]).length > 0 && (
                    <p className="doc-affil">{(doc.meta.affiliations as string[]).join(' · ')}</p>
                  )}
                </header>
              )}

              {shown.map((b) => (
                <DocBlock key={b.id} b={b} mode="dual" onSelect={() => {}} />
              ))}
            </div>
          </div>
        </div>
      </div>
    </section>
  )
}
