    return {"state": "pending", "email_sent": sent, "activate_url": None if sent else link}


@router.get("/activate")
def activate(token: str, conn: sqlite3.Connection = Depends(get_conn)) -> dict[str, Any]:
    row = conn.execute("SELECT * FROM activation_tokens WHERE token=?", (token,)).fetchone()
    if row is None:
        raise HTTPException(status.HTTP_400_BAD_REQUEST, "激活链接无效或已使用")
    activate_by_token(conn, token)
    return {"state": "active"}


@router.post("/login")
def login(
    body: LoginIn,
    response: Response,
    conn: sqlite3.Connection = Depends(get_conn),
) -> dict[str, Any]:
    user = user_by_email(conn, body.email)
    if user is None or not verify_password(user["password_hash"], body.password):
        raise HTTPException(status.HTTP_401_UNAUTHORIZED, "邮箱或密码不正确")
    if user["status"] == "disabled":
        raise HTTPException(status.HTTP_403_FORBIDDEN, "账号已被禁用")
    if user["status"] == "pending":
        raise HTTPException(status.HTTP_403_FORBIDDEN, "账号尚未激活，请查收激活邮件")
"}

