/* ─── auth — email register / login / reset ─────────────────────── */
[hidden] { display: none !important; }

.auth { display: none; min-height: 100vh; grid-template-columns: minmax(0, 1.02fr) minmax(0, 1fr); }
body.guest .auth { display: grid; }
body.guest .app,
body.guest .drawer,
body.guest .modal,
body.guest .overlay { display: none; }

.auth-aside {
  position: relative; overflow: hidden; display: flex; flex-direction: column;
  background: var(--fg); color: var(--surface); padding: 50px 54px;
}
.auth-aside::before {
  content: ''; position: absolute; inset: 0; pointer-events: none; opacity: .5;
  background-image:
    linear-gradient(color-mix(in oklch, var(--surface) 7%, transparent) 1px, transparent 1px),
    linear-gradient(90deg, color-mix(in oklch, var(--surface) 7%, transparent) 1px, transparent 1px);
  background-size: 46px 46px;
}
.auth-aside::after {
  content: ''; position: absolute; right: -190px; bottom: -210px; width: 480px; height: 480px;
  border-radius: 50%; pointer-events: none;
  background: radial-gradient(circle, color-mix(in oklch, var(--accent) 46%, transparent), transparent 68%);
}
.auth-aside > * { position: relative; z-index: 1; }
.auth-brand { display: flex; align-items: center; gap: 10px; }
.auth-brand .brand-mark { background: var(--surface); color: var(--fg); }
.auth-brand .brand-name { font-family: var(--font-display); font-size: 16px; font-weight: 600; display: block; }
.auth-brand .brand-sub { display: block; color: color-mix(in oklch, var(--surface) 55%, transparent); }

.auth-body { margin-top: auto; }
.auth-pitch h2 { font-family: var(--font-display); font-size: clamp(30px, 3.3vw, 42px); line-height: 1.08; letter-spacing: -.03em; font-weight: 600; }
.auth-pitch p { margin: 15px 0 0; max-width: 32ch; font-size: 14.5px; line-height: 1.62; color: color-mix(in oklch, var(--surface) 66%, transparent); }
.auth-steps { list-style: none; margin: 32px 0 0; padding: 0; display: grid; gap: 13px; }
.auth-steps li { display: grid; grid-template-columns: 26px 1fr; gap: 12px; font-size: 13.5px; line-height: 1.5; color: color-mix(in oklch, var(--surface) 66%, transparent); }
.auth-steps b { display: block; color: var(--surface); font-weight: 560; }
