/* ─── share links — a plan snapshot encoded into the URL hash ───── */
/* No backend in this prototype, so a read-only share carries the plan
   itself in the link. The viewer's own plans are never touched. */
function b64enc(s) {
  const bytes = new TextEncoder().encode(s);
  let bin = '';
  for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}
function b64dec(b) {
  const s = String(b).replace(/-/g, '+').replace(/_/g, '/');
  const bin = atob(s);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return new TextDecoder().decode(bytes);
}
function parseShareHash() {
  let raw = null;
  (location.hash || '').replace(/^#/, '').split('&').forEach(part => {
    const i = part.indexOf('=');
    if (i > 0 && part.slice(0, i) === 'share') raw = part.slice(i + 1);
  });
  if (!raw) return null;
  try {
    const obj = JSON.parse(b64dec(raw));
    if (!obj || obj.v !== 1 || !obj.plan || !obj.plan.id) return null;
    return obj.plan;
  } catch (e) { return null; }
}
const sharedPlan = parseShareHash();
const SHARE = { active: !!sharedPlan, plan: sharedPlan };
const shareLinkFor = pl => location.href.split('#')[0] + '#share=' + b64enc(JSON.stringify({ v: 1, at: Date.now(), plan: pl }));

const saved = readLS(LS) || {};
let plans = SHARE.active ? [SHARE.plan] : (Array.isArray(saved.plans) && saved.plans.length ? saved.plans : null);
if (!SHARE.active && !plans) {
  plans = seedPlans();
  const v1 = readLS(LS_V1);           /* migrate the earlier single-plan state once */
  if (v1) {
    const p0 = plans[0];
    if (v1.progress) for (const id in v1.progress) if (id in p0.progress) p0.progress[id] = v1.progress[id];
    if (v1.status) p0.status = v1.status;
    if (v1.notes) p0.notes = v1.notes;
    if (v1.activeId) p0.activeId = v1.activeId;
    if (v1.paceRange) p0.paceRange = v1.paceRange;
  }
}
plans.forEach(pl => {
  pl.papers = pl.papers || []; pl.status = pl.status || {}; pl.progress = pl.progress || {};
  pl.notes = pl.notes || {}; pl.queue = pl.queue || [];
  if (!pl.pace) pl.pace = blankPace();
  pl.papers.forEach(p => { if (typeof pl.progress[p.id] !== 'number') pl.progress[p.id] = p.pr; });
});

const state = {
  view: SHARE.active ? 'overview' : (saved.view || 'overview'),
  query: '', filter: 'all', sort: 'recent',
  readerMode: saved.readerMode || 'dual',
  fs: saved.fs || 14.5,
  rail: saved.rail || 'notes',
  selPara: null,
  activePlanId: SHARE.active ? plans[0].id : (plans.some(p => p.id === saved.activePlanId) ? saved.activePlanId : plans[0].id),
  plans: plans
};
const activePlan = () => state.plans.filter(p => p.id === state.activePlanId)[0] || state.plans[0];
const papers = () => activePlan().papers;
const save = () => { if (SHARE.active) return; try { localStorage.setItem(LS, JSON.stringify({ view: state.view, readerMode: state.readerMode, fs: state.fs, rail: state.rail, activePlanId: state.activePlanId, plans: state.plans })); } catch (e) {} };

const S = { get: p => activePlan().status[p.id] || p.st, set: (id, v) => { activePlan().status[id] = v; } };
const $ = (s, r) => (r || document).querySelector(s);
const $$ = (s, r) => Array.prototype.slice.call((r || document).querySelectorAll(s));
const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const countBy = key => papers().reduce((a, p) => { const v = key === 'st' ? S.get(p) : p.cv; a[v] = (a[v] || 0) + 1; return a; }, {});

function viewMeta(v) {
  const pl = activePlan();
  const m = {
    overview: { title: '总览', sub: pl.name + ' · 计划 ' + pl.goal + ' 篇' },
    library:  { title: '文献库', sub: '共 ' + papers().length + ' 篇 · 按最近更新排序' },
    reader:   { title: '阅读器', sub: '单栏阅读 · 中英左右对照 · 图表与原文同位' },
