    plans:    { title: '阅读计划', sub: '共 ' + state.plans.length + ' 个计划 · 各自独立记录文献与进度' },
    admin:    { title: '用户管理', sub: '共 ' + Object.keys(readAccounts()).length + ' 个账号 · 仅管理员可见' }
  };
  return m[v] || m.overview;
}

