/**
 * 极简 API 客户端 —— 只做四件事：拼 URL、带 cookie、解析错误、类型标注。
 *
 * 刻意不引入 axios / react-query：请求形态很少（十来个端点），
 * 加一层库只会让"错误怎么呈现"这件事被藏起来（决策⑨：保持单体简单）。
 */

import type {
  AdminUser, AuthConfig, Block, CodeSent, CurrentUser, GlossaryEntry, Note, Paper, PaperDoc,
  Plan, Share,
} from './types'

export class ApiError extends Error {
  status: number
  constructor(status: number, message: string) {
    super(message)
    this.status = status
  }
}

async function request<T>(path: string, init: RequestInit = {}): Promise<T> {
  const res = await fetch(path, {
    credentials: 'same-origin',
    headers: init.body && !(init.body instanceof FormData)
      ? { 'Content-Type': 'application/json' }
      : undefined,
    ...init,
  })
  if (res.status === 204) return undefined as T
  const text = await res.text()
  let data: unknown = null
  try { data = text ? JSON.parse(text) : null } catch { data = text }
  if (!res.ok) {
    const detail = (data as { detail?: string } | null)?.detail
    throw new ApiError(res.status, detail || `请求失败（${res.status}）`)
  }
  return data as T
}

const json = (body: unknown): RequestInit => ({ method: 'POST', body: JSON.stringify(body) })
const patch = (body: unknown): RequestInit => ({ method: 'PATCH', body: JSON.stringify(body) })

