{"file_path": "/Users/argszero/scm/github.com/argszero/papershelf/web/src/App.tsx", "content": "/** 应用外壳与路由表。
 *
 * 结构对齐原型（M5「复刻原型」）：**左侧栏 + 顶栏 + 视图区**，五个一级视图各占一条路由，
 * 刷新任何一个子路径都能落到对应页面（后端把所有未知 GET 交给 SPA）。
 *
 * ── 只读分享（⑩⑪）为什么是**同一套路由再挂一份**，而不是单个 `/share/:token` 页面 ──
 * 宿主 2026-09-11：「分享后的页面应该和分享者看到的一模一样，只是只读。」
 * 原型给出的正是这个结构：进分享模式只是给 `<body>` 加 `.readonly` + 挂 banner，
 * 侧栏/顶栏/五个视图**一个都没换**，点的还是同一套 `go('library')`。
 * 所以这里把 `PrivateShell` 的整张路由表在 `/share/:token/*` 下**原样再挂一遍**，
 * 只有两处不同：守卫从"必须有登录态"改成"必须有有效分享 payload"，
 * 以及外壳是只读版（写入口隐藏、链接带 token 前缀）。
 * 另写一个精简分享页会立刻偏离 ⑩（这正是被推翻的那版实现）。
 */

import { BrowserRouter, Navigate, Route, Routes, useLocation, useParams } from 'react-router-dom'

import { AuthProvider, useAuth } from './auth'
import { AdminPage } from './pages/Admin'
import { BoardPage } from './pages/Board'
import { ForgotPage } from './pages/Forgot'
import { LibraryPage } from './pages/Library'
import { LoginPage } from './pages/Login'
import { OverviewPage } from './pages/Overview'
import { PlansPage } from './pages/Plans'
import { ReaderPage } from './pages/Reader'
import { RegisterPage } from './pages/Register'
import { ShareProvider, useShare } from './shareContext'
import { PlanProvider } from './planContext'
import { NotFound } from './components'
import { Sidebar, ShareBanner, ShareInvalid } from './shell'

/** 五个一级视图 + 阅读器 + 计划详情。**分享与登录态共用这一张表。**
 *
 * 分享态下 `:paperId` / `:planId` 也照常匹配 —— 它们只是路径参数，
 * 取数走白名单端点，越权的那篇在服务端被 404（⑪ 的硬约束在后端）。
 */
function AppRoutes() {
  return (
    <Routes>
      <Route path="/" element={<OverviewPage />} />
      <Route path="/library" element={<LibraryPage />} />
      <Route path="/board" element={<BoardPage />} />
      <Route path="/plans" element={<PlansPage />} />
      <Route path="/plans/:planId" element={<PlansPage />} />
      <Route path="/reader" element={<ReaderPage />} />
      <Route path="/reader/:paperId" element={<ReaderPage />} />
      <Route path="/papers/:paperId" element={<ReaderPage />} />
      <Route path="/admin" element={<AdminPage />} />
      <Route path="*" element={<NotFound />} />
    </Routes>
  )
}

function PrivateShell() {
  const { user, loading } = useAuth()
  const loc = useLocation()
  if (loading) return <div className="auth-wrap"><p className="muted">加载中…</p></div>
  if (!user) return <Navigate to={`/login?next=${encodeURIComponent(loc.pathname)}`} replace />
  return (
    <div className="app">
      <Sidebar />
      <div className="main">
        <AppRoutes />
      </div>
    </div>
  )
}

/** 只读分享外壳：**同一套侧栏 + 视图**，只在最上面挂一条 `share-banner`。 */
function ShareShell() {
  const { token = '' } = useParams()
  return (
    <ShareProvider>
      <div className="app readonly">
        <Sidebar />
        <div className="main">
          <ShareBanner token={token} />
          <AppRoutes />
        </div>
      </div>
    </ShareProvider>
  )
}

/** 分享 payload 的有效性由 `ShareGate` 判定（真取一次数），失效/撤销/过期的
 *  链接给一句人话，而不是把空侧栏与 0 篇的页面摆出来。 */
function ShareGate() {
  const share = useShare()
  if (!share) return <ShareInvalid />
  return <ShareShell />
}

function Shell() {
  const loc = useLocation()
  // 认证页是独立版式（没有侧栏可言）
  if (/^\/(login|register|forgot)/.test(loc.pathname)) {
    return (
      <Routes>
        <Route path="/login" element={<LoginPage />} />
        <Route path="/register" element={<RegisterPage />} />
        <Route path="/forgot" element={<ForgotPage />} />
      </Routes>
    )
  }
  // 只读分享：整张路由表挂在 `/share/:token/*` 下，与登录态一一对应
  if (loc.pathname === '/share' || loc.pathname.startsWith('/share/')) {
    return (
      <Routes>
        <Route path="/share/:token/*" element={
          <ShareProvider>
            <PlanProvider>
              <ShareGate />
            </PlanProvider>
          </ShareProvider>
        } />
        <Route path="*" element={<NotFound title="链接不完整" hint="分享链接缺少令牌，请让分享者重新复制。" />} />
      </Routes>
    )
  }
  return (
    <PlanProvider>
      <PrivateShell />
    </PlanProvider>
  )
}

export function App() {
  return (
    <BrowserRouter>
      <AuthProvider>
        <Shell />
      </AuthProvider>
    </BrowserRouter>
  )
}
