content:
  text-decoration-color: color-mix(in oklch, var(--fg) 32%, transparent); text-underline-offset: 2px;
}
.link:hover { text-decoration-color: var(--fg); }
.btn-block { width: 100%; justify-content: center; }
.btn-lg { padding: 12px 16px; font-size: 14.5px; }

.auth-wrap { min-height: 100vh; display: grid; place-items: center; padding: 32px 20px; }

@media (max-width: 900px) {
  .auth { grid-template-columns: 1fr; }
  .auth-aside { display: none; }
  .auth-logo { display: block; }
}

/* ── 响应式 ─────────────────────────────────────────────────────────── */
/* 断点与原型一致（1200 / 920）：1200 是四列指标卡与双栏阅读开始挤的宽度，
   920 是侧栏横置的临界点。这两个数字是原型实测过的，不另立标准。 */
@media (max-width: 1200px) {
  .g-4 { grid-template-columns: repeat(2, 1fr); }
  .board { grid-template-columns: repeat(2, 1fr); }
  .reader-body { grid-template-columns: minmax(0, 1fr) 258px; }
  .pdf-page { padding: 38px 38px 22px; }
}
@media (max-width: 920px) {
  /* 侧栏**横置**为一条顶栏，而不是 `display: none` —— 隐藏会让窄屏彻底
     丢掉导航（原型在这一点上是对的，我之前偷懒隐藏是错的）。 */
  .app { grid-template-columns: 1fr; height: auto; min-height: 100vh; }
  .sidebar {
    position: sticky; top: 0; z-index: 20; flex-direction: row; align-items: center;
    gap: 6px; padding: 10px 12px; border-right: 0; border-bottom: 1px solid var(--border);
    overflow-x: auto;
  }
  .brand { padding: 0 10px 0 2px; }
  .brand-sub { display: none; }
  .plan-wrap { flex: none; }
  .plan-switch { width: auto; }
  .ps-sub, .ps-chev { display: none; }
  .ps-name { max-width: 110px; }
  .sidenav { flex-direction: row; }
  .side-sep, .side-goal { display: none; }
  .side-user { margin-left: auto; padding: 0; }
  .side-user .su-id { display: none; }
  .nav-item .nav-count { display: none; }

  .main { height: auto; overflow: visible; }
  .topbar { position: sticky; flex-wrap: wrap; height: auto; padding: 10px 14px; gap: 10px; }
  .search input { width: 130px; }
  .view-scroll, .view-scroll.is-fill { overflow: visible; }
  .view { padding: 18px 14px 40px; }

  .g-4, .g-3, .g-2 { grid-template-columns: 1fr !important; }
  .plan-grid, .board, .reader-body { grid-template-columns: 1fr; }
  .reader-rail { display: flex; border-top: 1px solid var(--border); }

  .doc-stage { padding: 16px 12px 48px; }
  .pdf-page { padding: 26px 20px 18px; }
  .lang-dual .blk-p, .lang-dual .doc-h, .lang-dual .doc-title, .lang-dual .cap {
    grid-template-columns: 1fr;
  }
  .lang-dual .blk-p .t-zh {
    margin-top: 7px; padding-left: 11px;
    border-left: 2px solid color-mix(in oklch, var(--muted) 42%, var(--border));
  }
  .doc-title { font-size: 22px; }

  /* 文献表在窄屏**横向滚动**，不硬挤成窄条（截图踩过：标题每行两个字） */
  .ptable .col-hide { display: none; }
  .table-scroll { overflow-x: auto; -webkit-overflow-scrolling: touch; }
  .table-scroll .ptable { min-width: 620px; }
}

