                  onClick={() => void logout()}>
            <IconLogout />
          </button>
        </div>
      )}
    </aside>
  )
}

/** 顶栏：标题 + 副标题 + 全局搜索 + 分享/导入动作。
 *
 * 搜索框把关键词落到 `?q=`（文献库读它）—— 这样"搜索"是一个**可分享、可回退**的状态，
 * 而不是藏在组件里的局部变量；原型也是这个行为（顶栏搜索直接驱动文献库筛选）。
 *
 * ⑩ 只读态：搜索照旧（这是读）、`导入文献` / `分享` 两个写入口整块不渲染
 * （原型 `body.readonly #importBtn, #shareBtn { display: none }`），
 * 换成一枚「只读分享」pill。
 */
export function TopBar({ title, sub, actions }: {
  title: string
  sub?: string
  actions?: React.ReactNode
}) {
  const { plan, papers } = usePlan()
  const share = useShare()
  const link = useLink()
  const nav = useNavigate()
  const loc = useLocation()
  const urlQ = new URLSearchParams(loc.search).get('q') || ''
  // 输入框是本地受控的（否则每敲一个字都会改 URL），但 URL 变了要跟上 ——
  // 用"上一次看到的 URL 关键词"做哨兵，在渲染期重同步，比 effect 少一帧闪烁。
  const [q, setQ] = useState(urlQ)
  const [syncedFrom, setSyncedFrom] = useState(urlQ)
  if (syncedFrom !== urlQ) {
    setSyncedFrom(urlQ)
    setQ(urlQ)
  }

  function submit(e: React.FormEvent) {
    e.preventDefault()
    const params = new URLSearchParams(q.trim() ? { q: q.trim() } : {})
    nav(`${link('/library')}${params.toString() ? `?${params}` : ''}`)
  }

  return (
    <header className="topbar">
      <div className="tb-title">
        <h1>{title}</h1>
        {sub && <span className="tb-sub">{sub}</span>}
      </div>
      <div className="tb-actions">
        {share && <span className="pill st-reading">只读分享</span>}
        <form className="search" onSubmit={submit} role="search">
          <IconSearch />
          <input type="search" value={q} onChange={(e) => setQ(e.target.value)}
                 placeholder="搜索标题、作者、标签…" aria-label="搜索文献" />
        </form>
        {actions}
        {!share && (
          <>
            <Link className="btn btn-secondary" to="/plans?share=1" title="分享当前计划">
              <IconShare />分享
            </Link>
            <Link className="btn btn-primary" to={`/plans?import=${plan?.id ?? ''}`}
                  title={plan ? `向「${plan.name}」导入文献` : '导入文献'}>
              <IconPlus />导入文献
            </Link>
          </>
        )}
        {papers.length === 0 && plan && (
          <span className="meta" style={{ whiteSpace: 'nowrap' }}>计划为空</span>
        )}
      </div>
    </header>
  )
}

/** 只读分享的提示带（原型 `.share-banner`）。
 *
 * 位置在**顶栏之下、视图之上** —— 属于外壳而不是某个页面，所以五个视图都带着它。
 * 尾部的按钮在原型里是「创建我的文献台」（原型没有后端，点了只是清掉 hash）；
 * 这里指向真实的注册页，是这条横幅唯一诚实的去处。
 */
export function ShareBanner({ token }: { token: string }) {
  const { plan } = usePlan()
  const nav = useNavigate()
  const [bad, setBad] = useState('')

  // 令牌无效/撤销/过期：整站取数全都会失败，这里**主动探一次**并给出口，
  // 否则匿名访客看到的是"空计划 + 0 篇"的死页面，不知道链接为什么没用。
  useEffect(() => {
    let alive = true
    api.sharedPlan(token).catch((e) => {
      if (alive) setBad(e instanceof Error ? e.message : '分享链接不可用')
    })
    return () => { alive = false }
  }, [token])

  return (
    <>
      <div className="share-banner">
        <span className="sb-dot" />
        <span>只读分享 · <b>{plan?.name || '阅读计划'}</b></span>
        <span className="sb-note">通过分享链接打开，内容不可编辑</span>
        <button className="btn btn-secondary btn-sm" onClick={() => nav('/register')}>
          创建我的文献台
        </button>
      </div>
      {bad && (
        <div className="banner error" style={{ margin: '12px 20px 0' }}>
          {bad} —— 请让分享者重新生成链接。
        </div>
      )}
    </>
  )
}

/** 分享令牌无效时的占位（`ShareShell` 的守卫）。
 *
 * 放在 `shell/` 里而不是 `pages/`：它不是某个视图，而是**整个分享作用域的守卫**，
 * 与 `PrivateShell` 里那条"未登录就跳登录页"是同一层的职责。
 */
export function ShareShell() {
  const share = useShare()
  const [bad, setBad] = useState('')
  const [ready, setReady] = useState(false)

  useEffect(() => {
    if (!share) return
    api.sharedPlans(share.token)
      .then(() => setReady(true))
      .catch((e) => setBad(e instanceof Error ? e.message : '分享链接不可用'))
  }, [share])

  if (!share || bad) {
    return (
      <div className="main">
        <NotFound title="链接不可用" hint={bad || '分享链接缺少令牌，请让分享者重新复制。'} />
      </div>
    )
  }
  if (!ready) return <div className="main"><div className="auth-wrap"><p className="muted">加载中…</p></div></div>

  return (
    <ShareShellInner token={share.token} />
  )
}

function ShareShellInner({ token }: { token: string }) {
  return (
    <div className="main">
      <ShareBanner token={token} />
      <Routes />
    </div>
  )
}

/** 占位：尚无计划时整站都用它（而不是让每个页面各写一份空状态）。 */
export function NoPlan() {
  const link = useLink()
  return (
    <div className="view">
      <div className="card">
        <h2 className="h3">还没有阅读计划</h2>
        <p className="muted" style={{ marginTop: 6 }}>
          一个计划 = 一个研究方向或一门课。文献、术语表与进度都挂在计划内。
        </p>
        <div className="row" style={{ marginTop: 16 }}>
          <Link className="btn btn-primary" to={link('/plans?new=1')}><IconPlus />新建阅读计划</Link>
        </div>
      </div>
    </div>
  )
}
