/** 分享面板（⑩⑪）—— 实时只读 + 可撤销 + 有有效期。
 *
 * 与术语表一起从旧 `Plan.tsx` 拆出来：这两块是**计划级设置**，
 * 现在挂在「阅读计划」抽屉里（原型也是从计划卡上开分享）。
 */

import { useCallback, useEffect, useState } from 'react'

import { api } from '../api'
import type { Share } from '../types'

export function SharePanel({ planId, onSwitch }: { planId: number; onSwitch?: () => void }) {
  const [shares, setShares] = useState<Share[]>([])
  const [days, setDays] = useState('0')
  const [msg, setMsg] = useState('')
  const [err, setErr] = useState('')

  const load = useCallback(async () => {
    if (!planId) return
    try { setShares(await api.shares(planId)) } catch { /* 无权或不存在：不阻塞页面 */ }
  }, [planId])
  useEffect(() => { void load() }, [load])

  async function create() {
    setErr(''); setMsg('')
    try {
      const r = await api.createShare(planId, Number(days) || 0)
      await navigator.clipboard?.writeText(r.url).catch(() => {})
      setMsg('已创建并复制到剪贴板（浏览器不允许剪贴板时请手动复制）。')
      await load()
    } catch (e) { setErr(e instanceof Error ? e.message : '创建失败') }
  }

  if (!planId) return <p className="muted">先选择一个计划。</p>

  return (
    <div className="stack">
      {err && <div className="banner error">{err}</div>}
      {msg && <div className="banner ok">{msg}</div>}

      <div className="row wrap" style={{ alignItems: 'flex-end' }}>
        <div className="field" style={{ maxWidth: 220 }}>
          <label>有效期</label>
          <select className="input" value={days} onChange={(e) => setDays(e.target.value)}>
            <option value="0">永久（可随时撤销）</option>
            <option value="1">1 天</option>
            <option value="7">7 天</option>
            <option value="30">30 天</option>
          </select>
        </div>
        <button className="btn btn-primary" onClick={() => void create()}>创建分享链接</button>
        {onSwitch && <button className="btn btn-ghost" onClick={onSwitch}>切到该计划查看</button>}
      </div>

      <p className="meta" style={{ lineHeight: 1.7 }}>
        链接是**实时只读**视图：持链接者无需登录即可阅读本计划下的文献，读到的永远是当前版本；
        随时可以撤销。⚠️ 公开分享等于向无鉴权者分发第三方版权内容，风险自负。
      </p>

      {shares.length === 0 && <p className="meta">还没有分享链接。</p>}
      {shares.map((s) => (
        <div className="card" key={s.token} style={{ padding: '12px 14px' }}>
          <div className="row wrap" style={{ gap: 8 }}>
            <span className={`pill ${s.state === 'active' ? 'st-read' : 'st-failed'}`}>
              {s.state === 'active' ? '有效' : s.state === 'expired' ? '已过期' : '已撤销'}
            </span>
            <span className="meta">{s.expires_at ? `到期 ${s.expires_at.slice(0, 10)}` : '永久'}</span>
            <span className="meta">创建于 {s.created_at.slice(0, 10)}</span>
            <div className="spacer" />
            {s.state === 'active' && (
              <>
                <button className="btn btn-ghost btn-sm"
                        onClick={() => void navigator.clipboard?.writeText(s.url)}>复制</button>
                <a className="btn btn-secondary btn-sm" href={`/share/${s.token}`}
