/** 总览 —— 原型的 `renderOverview`。
 *
 * 六个板块，全部只呈现**当前计划**的文献：
 *   ① 四张指标卡      ② 精读完成度（圆环 + 图例 + 堆叠条）+ 转换流水线
 *   ③ 阅读节奏（日/周柱状图 + 四项统计）+ 最近阅读
 *   ④ 需要关注（失败/久未开始/进度落后）+ 进度规划
 *
 * ⚠️ 阅读节奏的数据来自 `papers.status_at`（⑰：每次改状态都会盖时间戳）。
 * 这是本页**唯一**的推算成分，也是唯一一处必须诚实的地方：
 * 它统计的是"**被标记为已读/已整理**的时间"，不是真实的阅读行为。
 * 所以文案写「完成」而非「阅读」，并且旁边直接标出最大偏差来源。
 */

import { useMemo, useState } from 'react'
import { Link } from 'react-router-dom'

import { IconAlert, IconClock, IconFile, IconLang } from '../icons'
import { usePlan } from '../planContext'
import { useLink, useReadonly } from '../shareContext'
import { NoPlan, TopBar } from '../shell'
import { Legend, Ring, StatusBar, Tile } from '../components'
import {
  CONV, CONV_ORDER, dayKey, daysSince, fmtDate, isDone, relTime, startOfWeek,
} from '../vocab'
import type { Paper } from '../types'

type Range = 'd7' | 'd30' | 'w12'

const RANGES: Array<{ k: Range; label: string }> = [
  { k: 'd7', label: '近 7 天' },
  { k: 'd30', label: '近 30 天' },
  { k: 'w12', label: '近 12 周' },
]

function countBy<T extends string>(papers: Paper[], get: (p: Paper) => T): Record<string, number> {
  const out: Record<string, number> = {}
  for (const p of papers) { const v = get(p); out[v] = (out[v] || 0) + 1 }
  return out
}

export function OverviewPage() {
  const { plan, papers, loading } = usePlan()
  const link = useLink()
  const readonly = useReadonly()
  const [range, setRange] = useState<Range>('d7')

  const byStatus = countBy(papers, (p) => p.status)
  const byConv = countBy(papers, (p) => p.conv_state)
  const done = papers.filter((p) => isDone(p.status)).length
  const n = papers.length
  const pct = n ? Math.round((done / n) * 100) : 0

  if (!plan) return <><TopBar title="总览" sub="还没有阅读计划" /><NoPlan /></>

  return <OverviewBody {...{ plan, papers, link, readonly, loading, range, setRange, byStatus, byConv, done, n, pct }} />
}

/** 分出来纯粹是因为上面那个早退分支必须**在 hooks 之前**（React 的规则）。 */
function OverviewBody({ plan, papers, link, readonly, loading, range, setRange, byStatus, byConv, done, n, pct }: {
  link: (p: string) => string

/** 状态 / 转换状态 / 时间格式 —— 全站唯一的文案与配色来源。
 *
 * 颜色一律写成 `var(--st-*)`（不是字面色值）：内联 style 里也能用 CSS 变量，
 * 于是**调色板只存在于 styles.css 一处**，甜甜圈、堆叠条、看板圆点、
 * 状态药丸永远不会互相漂移（原型里同一套色被复制了四遍）。
 */

import type { ConvState, PaperStatus } from './types'

interface Vocab {
  /** 中文标签（界面与看板列头共用） */
  label: string
  /** 药丸 / 圆点的 CSS 类 */
  cls: string
  /** 数据可视化用的颜色（CSS 变量） */
  color: string
}

/** ⑰ 四态阅读阶段 —— 看板四列的顺序就是这个数组的顺序。 */
export const STATUS: Record<PaperStatus, Vocab> = {
  unread:   { label: '待读',   cls: 'st-unread',  color: 'var(--st-unread)' },
  reading:  { label: '在读',   cls: 'st-reading', color: 'var(--st-reading)' },
  read:     { label: '已读',   cls: 'st-read',    color: 'var(--st-read)' },
  reviewed: { label: '已整理', cls: 'st-review',  color: 'var(--st-review)' },
}

export const STATUS_ORDER: PaperStatus[] = ['unread', 'reading', 'read', 'reviewed']

/** 「已精读」的定义：已读 + 已整理（看板与总览共用一个口径）。 */
export function isDone(s: PaperStatus): boolean {
  return s === 'read' || s === 'reviewed'
}

export const CONV: Record<ConvState, { label: string; cls: string; color: string }> = {
  none:   { label: '待转换', cls: 'st-unread',     color: 'var(--st-unread)' },
  queued: { label: '排队中', cls: 'st-converting', color: 'var(--warn)' },
  doing:  { label: '转换中', cls: 'st-converting', color: 'var(--warn)' },
  done:   { label: '已生成', cls: 'st-read',       color: 'var(--st-read)' },
  failed: { label: '转换失败', cls: 'st-failed',   color: 'var(--danger)' },
}

export const CONV_ORDER: ConvState[] = ['done', 'doing', 'queued', 'none', 'failed']

/** 把字数压到 `n` 个字以内，用于卡片标题。 */
export function clip(s: string | null | undefined, n = 18): string {
  const t = (s || '').trim()
  return t.length > n ? `${t.slice(0, n)}…` : t
}

const DAY = 86_400_000

/** 后端时间戳是 ISO（UTC，秒级精度）→ 一律按**本地时间**显示。 */
export function fmtDate(iso: string | null | undefined): string {
  if (!iso) return '—'
  const d = new Date(iso)
  if (Number.isNaN(d.getTime())) return '—'
  const p = (n: number) => String(n).padStart(2, '0')
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`
}

